--   https://resultados.tse.jus.br/oficial/ele2026/6259/dados/sp/sp-c0005-e006259-u.json
--     sha256 55ae5a371b797c0817494e37b38987af4408af5a3ae45ae2a72f6739f1019a86 (gerado pelo TSE em 05/10/2026 11:44:31)
--   https://resultados.tse.jus.br/oficial/ele2026/6259/dados/to/to-c0005-e006259-u.json
--     sha256 0764a9b9eb3124e377796660415acdefb2d3e9acf67b8e244012ddcaa39cfe5a (gerado pelo TSE em 04/10/2026 21:18:59)
--
-- Escrita: candidaturas_fase_2026 (inserção; nenhuma linha pode existir antes)
-- e recibo em coleta_log com before/after de cada linha. Candidatura com
-- atualizacao_encerrada_em sai da coorte de atualização; a ficha continua no
-- ar e nenhum dado é apagado. Pendências do plano (0) não são tocadas.
--
-- NÃO aplicar por `supabase db push` nem por automação: produção só recebe
-- esta migration pelo workflow apply-fase-eleitoral-production (conjunto turno-1).
BEGIN;
SET LOCAL TIME ZONE 'UTC';
LOCK TABLE public.candidaturas_fase_2026 IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.candidatos IN SHARE MODE;

DO $apply$
DECLARE
  quantidade integer;
  encerrada date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.candidatos) THEN
    RAISE NOTICE 'fase-turno-1-20261005180206: coorte ausente; resultado ignorado (replay)';
    RETURN;
  END IF;

  IF current_setting('pf.replay', true) = 'true' THEN
    RAISE NOTICE 'fase-turno-1-20261005180206: resultado ignorado apenas no replay descartável';
    RETURN;
  END IF;

  CREATE TEMP TABLE pf_fase_plano_20261005180206 (
    candidato_id uuid PRIMARY KEY, slug text NOT NULL, sq text, sq_antes text, cargo text NOT NULL,
    fase_antes text NOT NULL, fase_depois text NOT NULL, turno smallint NOT NULL, encerra boolean NOT NULL,
    situacao_tse text, fonte_url text, fonte_sha256 text
  ) ON COMMIT DROP;

  -- Preimagem: cada candidatura existe, está no ar, com o SQ e o cargo do plano.
  IF (SELECT count(*) FROM pf_fase_plano_20261005180206 p
       JOIN public.candidatos c ON c.id = p.candidato_id
      WHERE c.slug = p.slug AND c.sq_candidato_2026 IS NOT DISTINCT FROM p.sq_antes AND c.cargo_disputado = p.cargo
        AND c.publicavel IS TRUE AND c.status <> 'removido') <> 512 THEN
    RAISE EXCEPTION 'fase-turno-1-20261005180206: preimagem de candidatos divergiu';
  END IF;
  IF EXISTS (SELECT 1 FROM public.candidaturas_fase_2026 f JOIN pf_fase_plano_20261005180206 p ON p.candidato_id = f.candidato_id) THEN
    RAISE EXCEPTION 'fase-turno-1-20261005180206: candidatura já tem fase gravada';
  END IF;

  -- Preimagem integral de cada linha (nula no 1º turno), para o recibo e o rollback.
  CREATE TEMP TABLE pf_fase_plano_20261005180206_antes ON COMMIT DROP AS
    SELECT f.candidato_id, to_jsonb(f) AS antes
    FROM public.candidaturas_fase_2026 f JOIN pf_fase_plano_20261005180206 p ON p.candidato_id = f.candidato_id;

  -- @write tabela=candidaturas_fase_2026 ref=fase-turno-1-20261005180206 campos=candidato_id,sq_candidato_2026,cargo_disputado,fase_eleitoral,fase_turno,atualizacao_encerrada_em,situacao_tse,fonte_url,fonte_sha256,migration_version,registrado_em
     situacao_tse, fonte_url, fonte_sha256, migration_version, registrado_em)
  SELECT p.candidato_id, p.sq, p.cargo, p.fase_depois, p.turno,
         CASE WHEN p.encerra THEN encerrada END,
         p.situacao_tse, p.fonte_url, p.fonte_sha256, '20261005180206', now()
  FROM pf_fase_plano_20261005180206 p
  ON CONFLICT (candidato_id) DO NOTHING;
  GET DIAGNOSTICS quantidade = ROW_COUNT;
  IF quantidade <> 512 THEN
    RAISE EXCEPTION 'fase-turno-1-20261005180206: escrita esperada=512 atual=%', quantidade;
  END IF;

  -- @write tabela=coleta_log ref=migration:20261005180206 campos=fonte,escopo,alvo,resultado,volume,detalhe,url,execucao,natureza
  SELECT 'tse-resultados-2026', 'global', 'candidaturas_fase_2026', 'encontrado', 512,
         jsonb_build_object(
           'resumo', 'Resultado oficial do 1º turno de 2026 gravado para 512 candidatura(s): mudancas=512, pendentes=0, encerram=496, nao_eleito=368, fora_da_disputa=54, segundo_turno=16, eleito=74.',
           'plano_sha256', '110db31e0496bd35110299a2b73dbdf380beff78df1541a5ddcb699c761b6fdf',
           'turno', 1,
           'linhas', jsonb_agg(jsonb_build_object(
             'slug', p.slug,
             'candidato_id', p.candidato_id,
             'before', (SELECT a.antes FROM pf_fase_plano_20261005180206_antes a WHERE a.candidato_id = p.candidato_id),
             'after', to_jsonb(f)) ORDER BY p.slug)
         )::text,
         'https://resultados.tse.jus.br/oficial/ele2026/6259/dados/ba/ba-c0003-e006259-u.json',
         'migration:20261005180206', 'escrita'
  FROM pf_fase_plano_20261005180206 p
  JOIN public.candidaturas_fase_2026 f ON f.candidato_id = p.candidato_id;

  IF (SELECT count(*) FROM public.candidaturas_fase_2026 f JOIN pf_fase_plano_20261005180206 p ON p.candidato_id = f.candidato_id
       WHERE f.migration_version = '20261005180206' AND f.fase_eleitoral = p.fase_depois AND f.fase_turno = p.turno
         AND (f.atualizacao_encerrada_em IS NOT NULL) = p.encerra) <> 512 THEN
    RAISE EXCEPTION 'fase-turno-1-20261005180206: pós-condição falhou';
  END IF;
END
$apply$;

COMMIT;
